<template>
  <el-dialog title="到货截单与采购终止" :visible.sync="visible" width="min(1120px, 96vw)" top="4vh" append-to-body :close-on-click-modal="false" :close-on-press-escape="!saving" @closed="stop">
    <div class="cutoff-body" v-loading="loading" v-if="document">
      <div class="identity"><strong>{{ kind === 'receipt' ? document.noSn : document.poSn }}</strong><span>{{ document.noName || document.poName }}</span><el-tag size="small" type="info">{{ kind === 'receipt' ? report.operations.some(o => o.scope === 'PURCHASE') ? '随来源采购终止处理' : '本批截单保留采购需求' : '逐批确认，原单据保留' }}</el-tag></div>
      <template v-if="creating && eligible">
        <h4>1. 处理目的</h4><el-radio-group v-model="mode" class="purposes"><el-radio label="WITHDRAW" border><strong>撤回到货安排</strong><p>截停未收部分，保留采购需求。完成核对后释放到货额度，重新安排须生成新单。</p></el-radio><el-radio v-if="kind === 'purchase'" label="TERMINATE" border><strong>终止剩余采购</strong><p>截停全部未完成到货安排，确认后关闭剩余采购需求；处理中禁止新增到货单。</p></el-radio></el-radio-group>
        <h4>2. 到货范围</h4><el-table :data="candidates" size="small"><el-table-column v-if="kind === 'purchase' && mode === 'WITHDRAW'" label="选择" width="60"><template slot-scope="s"><el-checkbox v-model="selected" :label="s.row.id" :disabled="!!s.row.cutoffState && s.row.cutoffState !== 'COMPLETED'"><span /></el-checkbox></template></el-table-column><el-table-column label="到货单" prop="noSn" min-width="270" /><el-table-column label="计划" prop="numberExpected" width="90" /><el-table-column label="已入库" prop="numberActually" width="100" /><el-table-column label="处理范围" min-width="220"><template slot-scope="s">{{ s.row.cutoffState && s.row.cutoffState !== 'COMPLETED' ? '已有原申请待核对' : '核对未收余量，已入库不回退' }}</template></el-table-column></el-table>
        <p v-if="!candidates.length && mode === 'TERMINATE'" class="hint">没有未结束的到货安排，本次仅关闭尚未安排的采购需求。</p>
        <h4>3. 截单原因</h4><el-input v-model.trim="reason" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="填写截单原因（必填）" />
        <el-alert class="notice" title="申请成功不表示仓库已截停" description="待确认数量继续占用到货额度；期间有效收货回传正常记账。仓库截停、实收及记账均核对完成后才释放额度。部分收货关闭余量按仓库能力开放，不支持时需人工核对。" type="warning" show-icon :closable="false" />
      </template>
      <section v-for="op in report.operations" :key="op.id" class="operation"><div class="operation-heading"><strong>{{ op.scope === 'PURCHASE' ? '终止剩余采购' : '撤回到货安排' }}</strong><el-tag :type="op.state === 'COMPLETED' ? 'success' : 'warning'" size="small">{{ op.state === 'COMPLETED' ? '全部处理完成' : op.state === 'WAIT_REVIEW' ? '待人工核对' : '处理中 / 待确认' }}</el-tag><span>{{ parseTime(op.create_time) }} · {{ op.operator_name }}</span></div><p class="hint">原因：{{ op.reason }}</p>
        <el-table :data="op.items" size="small"><el-table-column label="到货单 / 入库单" min-width="260"><template slot-scope="s">{{ s.row.receipt_sn }}<div class="hint">{{ s.row.ticket_sn || '尚未生成入库单' }}</div></template></el-table-column><el-table-column label="仓库截停" width="155"><template slot-scope="s">{{ warehouseLabel(s.row.warehouse_state) }}</template></el-table-column><el-table-column label="实收与额度" min-width="170"><template slot-scope="s">{{ s.row.state === 'COMPLETED' ? '已核对，截停 ' + s.row.cancelled_quantity + ' 件' : s.row.state === 'POSTING_PENDING' ? '实收记账待确认，保留额度' : '保留原到货安排额度' }}</template></el-table-column><el-table-column label="处理说明" min-width="210"><template slot-scope="s">{{ s.row.last_error || (s.row.state === 'COMPLETED' ? '原计划、实收及截停数量保留' : '等待核对原申请') }}<div v-if="s.row.manual_evidence" class="hint">人工依据：{{ s.row.manual_evidence }}</div></template></el-table-column><el-table-column label="操作" width="155"><template slot-scope="s"><el-button v-if="s.row.ticket_sn" v-hasPermi="['warehouse:wms:log']" type="text" @click="logs(s.row)">交互链路</el-button><el-button v-if="s.row.state !== 'COMPLETED' && s.row.ticket_id && !['CONFIRMED','MANUAL_CONFIRMED'].includes(s.row.warehouse_state)" v-hasPermi="['warehouse:poInfo:cutoffReview']" type="text" @click="openManual(s.row)">登记仓库截停确认</el-button></template></el-table-column></el-table>
        <p v-if="op.last_error" class="warning">{{ op.last_error }}</p><p v-if="!op.items.length" class="hint">本次仅关闭尚未安排的采购需求，无需通知仓库。</p>
      </section>
      <section v-if="report.reviews.length" class="operation"><h4>取消后收货回传核对</h4><el-alert title="待核对回传没有新增库存，拒绝后也不会入账。确认真实收货须核对采购额度及原批次，成功后按原幂等键入账。" type="warning" :closable="false" /><el-table :data="report.reviews" size="small"><el-table-column label="入库单 / 消息" min-width="260"><template slot-scope="s">{{ s.row.ticket_sn }}<div class="hint">{{ s.row.message_id }}</div></template></el-table-column><el-table-column label="核对状态" width="125"><template slot-scope="s">{{ { WAIT_REVIEW: '待人工核对', ACCEPTED: '确认实际收货', REJECTED: '已拒绝回传' }[s.row.state] }}</template></el-table-column><el-table-column label="说明" min-width="240"><template slot-scope="s">{{ s.row.reason || s.row.conflict_message }}</template></el-table-column><el-table-column label="操作" width="90"><template slot-scope="s"><el-button v-if="s.row.state === 'WAIT_REVIEW'" v-hasPermi="['warehouse:poInfo:cutoffReview']" type="text" @click="openReview(s.row)">人工核对</el-button></template></el-table-column></el-table></section>
    </div>
    <span slot="footer"><el-button :disabled="saving" @click="visible=false">关闭</el-button><el-button :loading="loading" @click="refresh">刷新结果</el-button><el-button v-if="pending" v-hasPermi="['warehouse:poInfo:cutoff']" :loading="saving" @click="retry">核对 / 重试原申请</el-button><el-button key="new" v-if="eligible && !creating" v-hasPermi="['warehouse:poInfo:cutoff']" @click="creating=true">发起新截单</el-button><el-button key="submit" v-if="creating && eligible" v-hasPermi="['warehouse:poInfo:cutoff']" type="danger" :disabled="!reason || kind === 'purchase' && mode === 'WITHDRAW' && !selected.length" :loading="saving" @click="submit">{{ mode === 'TERMINATE' ? '申请终止剩余采购' : '申请到货单截单' }}</el-button></span>
    <el-dialog class="cutoff-subdialog" top="4vh" title="登记仓库截停确认" :visible.sync="manualVisible" width="min(850px, 92vw)" append-to-body :close-on-click-modal="false"><template v-if="manual"><el-alert title="先确认仓库已停止本批后续收货，再逐行核对最终实收。数量不一致须先补齐或核对回传，不能强行关闭。" type="warning" :closable="false" /><p>{{ manual.item.receipt_sn }} / {{ manual.item.ticket_sn }}</p><el-form label-position="top" size="small"><el-form-item label="仓库单号"><el-input v-model.trim="manual.external_order" maxlength="100" /></el-form-item><el-form-item label="仓库确认依据"><el-input v-model.trim="manual.evidence" type="textarea" maxlength="500" show-word-limit placeholder="填写仓库确认记录、工单或凭证编号（必填）" /></el-form-item></el-form><el-table :data="manual.lines" max-height="260" size="small"><el-table-column label="商品 / SKU" prop="sku" min-width="220" /><el-table-column label="仓库最终实收正品" width="210"><template slot-scope="s"><el-input-number v-model="s.row.good" :min="0" :precision="0" size="small" /></template></el-table-column><el-table-column label="仓库最终实收次品" width="210"><template slot-scope="s"><el-input-number v-model="s.row.bad" :min="0" :precision="0" size="small" /></template></el-table-column></el-table><el-checkbox v-model="manual.confirmed_stopped" class="notice">已核实仓库停止后续收货，最终实收与系统回传一致</el-checkbox></template><span slot="footer"><el-button :disabled="saving" @click="manualVisible=false">取消</el-button><el-button type="primary" :disabled="!manual || !manual.evidence || !manual.external_order || !manual.confirmed_stopped" :loading="saving" @click="confirmManual">登记确认并继续核对</el-button></span></el-dialog>
    <el-dialog class="cutoff-subdialog" top="4vh" title="核对取消后收货回传" :visible.sync="reviewVisible" width="min(850px, 92vw)" append-to-body :close-on-click-modal="false"><template v-if="review"><p>{{ review.ticket_sn }} · 消息 {{ review.message_id }}</p><el-table :data="review.receipt.lines" max-height="260" size="small"><el-table-column label="SKU" prop="sku" /><el-table-column label="批次" prop="batch" /><el-table-column label="正品" prop="good" width="90" /><el-table-column label="次品" prop="bad" width="90" /></el-table><el-radio-group v-model="decision" class="notice"><el-radio label="REJECT">拒绝回传，不入账</el-radio><el-radio label="ACCEPT">确认实际收货，继续入账</el-radio></el-radio-group><el-alert v-if="decision === 'ACCEPT'" title="仅在实际收货已核实且采购额度未被其他批次使用时确认；额度不足会阻止处理，需另行核对采购安排。" type="warning" :closable="false" /><el-input v-model.trim="reviewReason" type="textarea" maxlength="500" show-word-limit placeholder="填写核对依据与处理说明（必填）" class="notice" /><el-checkbox v-if="decision === 'ACCEPT'" v-model="confirmedActual" class="notice">已核实仓库真实收货及回传批次</el-checkbox></template><span slot="footer"><el-button :disabled="saving" @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!reviewReason || decision === 'ACCEPT' && !confirmedActual" @click="decide">确认核对结果</el-button></span></el-dialog>
  </el-dialog>
</template>
<script>
import * as api from '@/api/purchase/workspace'
export default {
  data() { return { visible: false, kind: 'receipt', id: null, document: null, loading: false, saving: false, creating: false, mode: 'WITHDRAW', selected: [], reason: '', report: { operations: [], reviews: [] }, timer: null, polls: 0, manualVisible: false, manual: null, reviewVisible: false, review: null, decision: 'REJECT', reviewReason: '', confirmedActual: false } },
  computed: {
    candidates() { return this.kind === 'receipt' ? [this.document] : (this.document.receipts || []).filter(n => [1, 2, 3].includes(n.noState)) },
    eligible() { return this.document && (this.kind === 'receipt' ? [1, 2, 3].includes(this.document.noState) && !this.document.cutoffState : [2, 3].includes(this.document.poState) && this.document.cutoffState !== 'PROCESSING') },
    pending() { return this.report.operations.some(o => o.state !== 'COMPLETED') }
  },
  beforeDestroy() { this.stop() },
  methods: {
    async open(kind, row) { this.stop(); this.kind = kind; this.id = row.id; this.document = null; this.reason = ''; this.selected = []; this.mode = 'WITHDRAW'; this.creating = false; this.report = { operations: [], reviews: [] }; this.polls = 0; this.visible = true; await this.refresh(); this.creating = !this.report.operations.length && this.eligible },
    stop() { clearTimeout(this.timer); this.timer = null },
    async refresh() { if (this.loading || !this.id) return; this.stop(); this.loading = true; try { const [d, r] = await Promise.all([api.detail(this.kind, this.id), api.cutoffReport(this.kind, this.id)]); this.document = d.data; this.report = r.data; this.polls++; if (this.visible && this.report.operations.some(o => o.state === 'PROCESSING') && this.polls < 40) this.timer = setTimeout(() => this.refresh().catch(() => {}), 3000); this.$emit('changed') } finally { this.loading = false } },
    async submit() { if (this.saving || !this.reason || !this.eligible) return; this.saving = true; try { await api.requestCutoff(this.kind, this.id, { reason: this.reason, mode: this.mode, cutoff_version: this.report.cutoff_version, ...(this.kind === 'purchase' && this.mode === 'WITHDRAW' ? { receipt_ids: this.selected } : {}) }); this.creating = false; await this.refresh() } finally { this.saving = false } },
    async retry() { if (this.saving) return; this.saving = true; try { await api.retryCutoff(this.kind, this.id, { cutoff_version: this.report.cutoff_version }); this.polls = 0; await this.refresh() } finally { this.saving = false } },
    warehouseLabel(state) { return ({ CONFIRMED: '仓库已确认截停', MANUAL_CONFIRMED: '人工核实仓库截停', NOT_REQUIRED: '本地取消，无需通知', FULL_RECEIVED: '已全部实收，无待截余量', FINAL_RECEIPT: '仓库最终收货已确认', PENDING: '尚未明确确认' })[state] || state },
    logs(item) { this.visible = false; this.$router.push({ path: '/oms-supplychain/wmsLogs', query: { numberType: 'ARRIVAL', number: item.receipt_sn, allTime: 'true' } }) },
    async openManual(item) { if (this.saving) return; const d = (await api.detail('ticket', item.ticket_id)).data; this.manual = { item, external_order: d.externalOrder || '', evidence: '', confirmed_stopped: false, lines: d.lines.map(g => ({ id: g.id, sku: g.skuSn, good: g.numberZp || 0, bad: g.numberCp || 0 })) }; this.manualVisible = true },
    async confirmManual() { if (this.saving) return; this.saving = true; try { await api.confirmCutoff(this.manual.item.id, this.manual); this.manualVisible = false; await this.refresh() } finally { this.saving = false } },
    async openReview(row) { this.review = (await api.inboundReview(row.id)).data; this.decision = 'REJECT'; this.reviewReason = ''; this.confirmedActual = false; this.reviewVisible = true },
    async decide() { if (this.saving) return; this.saving = true; try { await api.decideInboundReview(this.review.id, { decision: this.decision, reason: this.reviewReason, control_version: this.review.control_version, confirmed_actual: this.confirmedActual }); this.reviewVisible = false; await this.refresh() } finally { this.saving = false } }
  }
}
</script>
<style scoped>
.cutoff-subdialog ::v-deep .el-dialog__body{max-height:calc(100vh - 240px);overflow:auto}.cutoff-body{max-height:calc(100vh - 240px);overflow:auto;padding-right:8px;color:#35465c}.identity,.operation-heading{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.identity{background:#f4f7fc;border-radius:8px;padding:14px;font-size:13px}.identity strong{overflow-wrap:anywhere}.purposes{display:flex;gap:12px;flex-wrap:wrap}.purposes .el-radio{white-space:normal;height:auto;margin:0!important;padding:14px;flex:1;min-width:240px}.purposes p,.hint{font-size:12px;color:#7c899b;line-height:1.8}.purposes p{margin:8px 0 0}.purposes ::v-deep .el-radio__label{white-space:normal}.operation{margin-top:18px;padding:14px;border:1px solid #e1e8f2;border-radius:8px}.operation-heading span{font-size:12px;color:#7b899d}.notice{margin-top:16px}.warning{color:#b47b16;font-size:13px;line-height:1.7}h4{font-size:14px;margin:18px 0 12px}
</style>
